  (1, 1, 'jashori-khejurer-patali', 'যশোরের প্রিমিয়াম খেজুর পাটালি গুড়', '১০০% খাঁটি ও চিনিমুক্ত। যশোরের গাছিদের দীর্ঘদিনের অভিজ্ঞতায় মাটির চুলায় নিপুণ আঁচে জ্বাল দেওয়া আদি পাটালি।', 'যশোরের রূপদিয়া ও বাঘারপাড়ার বিখ্যাত খেজুর বাগান থেকে ভোরবেলার টাটকা রস সংগ্রহ করে দীর্ঘ ৩–৪ ঘণ্টা মাটির উনুনে জ্বাল দিয়ে তৈরি হয় এই বিশেষ পাটালি গুড়।', 480.00, 500, 'in_stock', 'https://images.unsplash.com/photo-1599785209707-a456fc1337bb?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1599785209707-a456fc1337bb?auto=format&fit=crop&w=800&q=80"]', 1, 1),
  (2, 2, 'premiere-nolen-gur-liquid', 'সুবাসিত আদি নলেন গুড় (ঝুলা/তরল)', 'শীতের প্রথম রসের অতুলনীয় ঘ্রাণে ভরপুর গাঢ় তরল নলেন গুড়। পিঠাপুলি, পায়েস ও ক্ষীরের জন্য অতুলনীয়।', 'নলেন গুড় হলো বাঙালির শীতের সেরা উপহার। শীতের কনকনে ঠাণ্ডা রাতে গাছের ডগা চেঁছে হাঁড়িতে জমা হওয়া প্রথম রস জ্বাল দিয়ে তৈরি হয় এই তরল নলেন গুড়।', 750.00, 1000, 'in_stock', 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=800&q=80"]', 1, 1),
  (3, 3, 'khejurer-dana-gur-special', 'বিশেষ দানাদার খয়েরি খেজুর গুড়', 'জিভে দিলে দানা দানা ক্রাঞ্চি অনুভূতি। চা, কফি বা সরাসরি খাওয়ার জন্য অতুলনীয় পুষ্টিকর গুড়।', 'ঐতিহ্যবাহী গাছিদের বিশেষ কৌশল ও তাপমাত্রা নিয়ন্ত্রণের মাধ্যমে রস যখন গাঢ় হয়ে জমাট বাঁধার ঠিক আগের মুহূর্তে নাড়িয়ে তৈরি করা হয় এই দানাদার গুড়।', 520.00, 500, 'in_stock', 'https://images.unsplash.com/photo-1608039755401-742074f0548d?auto=format&fit=crop&w=800&q=80', '["https://images.unsplash.com/photo-1608039755401-742074f0548d?auto=format&fit=crop&w=800&q=80"]', 0, 1)
